o_route_colours:add_dropdown_value("pale", "mct_derpy_more_resources_route_colours_pale_text", "mct_derpy_more_resources_route_colours_pale_tooltip", false)
o_route_colours:add_dropdown_value("colourblind", "mct_derpy_more_resources_route_colours_colourblind_text", "mct_derpy_more_resources_route_colours_colourblind_tooltip", false)
